package com.hpe.morpheus.harvester.plugin.apihelper

import com.hpe.morpheus.harvester.plugin.utils.HarvesterConstants
import com.morpheusdata.model.ComputeServerGroup
import com.morpheusdata.response.ServiceResponse
import groovy.util.logging.Slf4j

/**
 * Helper class for Harvester DataVolume API operations
 * Purpose: Provides high-level API methods for Harvester DataVolume operations using CDI (Containerized Data Importer)
 * Author: Generated by GitHub Copilot
 * Date: September 18, 2025
 */
@Slf4j
class DataVolumeApiHelper {
    // Instance fields for configuration
    private ComputeServerGroup serverGroup
    private HarvesterApiClient apiClient

    /**
     * Create instance with ComputeServerGroup credentials
     * @param serverGroup ComputeServerGroup containing credentials
     */
    DataVolumeApiHelper(ComputeServerGroup serverGroup = null) {
        this.serverGroup = serverGroup
        this.apiClient = new HarvesterApiClient(serverGroup)
        log.debug "Initialized DataVolumeApiHelper with authentication"
    }

    /**
     * Fetch DataVolumes from Harvester API
     * @param namespaceDataVolumeMap Optional parameter to return data organized by namespace:name key
     * @return Map containing success status, list of datavolumes, and optional namespace map
     */
    def getDataVolumes() {
        def ret = [success: true, datavolumes: []]

        try {
            ServiceResponse dataVolumesResponse = apiClient.get(HarvesterConstants.HARVESTER_API_V1_DATAVOLUMES)

            if (dataVolumesResponse.success) {
                def dataVolumes = dataVolumesResponse.data?.items ?: []
                dataVolumes.each { dv ->
                    String dvName = dv.metadata.name
                    String dvNamespace = dv.metadata.namespace

                    // Filter out system namespaces
                    if (!CommonApiHelper.isSystemNamespace(dvNamespace)) {
                        def storageClass = dv.spec?.storage?.storageClassName
                        def requestedStorage = dv.spec?.storage?.resources?.requests?.storage
                        if(dv.spec?.resources){
                            requestedStorage = dv.spec?.resources?.requests?.storage
                            storageClass = dv.spec?.resources?.storageClassName
                        } else if(dv.spec?.pvc){
                            requestedStorage = dv.spec?.pvc?.resources?.requests?.storage
                            storageClass = dv.spec?.pvc?.storageClassName
                        }

                        String claimName = dv.status?.claimName

                        // When storageClass is absent from the spec (uses cluster default StorageClass),
                        // resolve it via a targeted GET on the bound PVC — avoids fetching all PVCs upfront
                        if (!storageClass && claimName) {
                            String pvcUrl = "/api/v1/namespaces/${dvNamespace}/persistentvolumeclaims/${claimName}"
                            ServiceResponse pvcResponse = apiClient.get(pvcUrl)
                            if (pvcResponse.success && pvcResponse.data?.spec?.storageClassName) {
                                storageClass = pvcResponse.data.spec.storageClassName
                                log.debug("DataVolume ${dvName}: resolved storageClass '${storageClass}' from bound PVC '${claimName}'")
                            } else {
                                log.warn("DataVolume ${dvName} in namespace ${dvNamespace}: could not resolve storageClass from bound PVC '${claimName}'")
                            }
                        }

                        if (!requestedStorage) {
                            log.debug("DataVolume ${dvName} in namespace ${dvNamespace} has no requested storage size defined. Datavolume:${dv}, spec: ${dv.spec}")
                        }
                        if (!storageClass) {
                            log.warn("DataVolume ${dvName} in namespace ${dvNamespace} has no storageClass defined after PVC fallback. Datavolume:${dv}, spec: ${dv.spec}")
                        }

                        def sizeBytes = requestedStorage ? VirtualMachineApiHelper.parseVolumeSize(requestedStorage) : 0L

                        def dataVolumeDetails = [
                                uid: dv.metadata.uid,
                                name: dvName,
                                namespace: dvNamespace,
                                storageClass: storageClass,
                                sizeBytes: sizeBytes,
                                status: dv.status?.phase ?: 'Unknown',
                                ownerReferences: dv.metadata?.ownerReferences,
                                dataSource: dv.spec?.source,
                                claimName: dv.status?.claimName, // The PVC created by this DataVolume
                        ]
                        ret.datavolumes << dataVolumeDetails
                    }
                }
                ret.success = true
                log.info "Successfully fetched ${ret.datavolumes.size()} DataVolumes from Harvester"
            } else if (isCdiNotInstalled(dataVolumesResponse)) {
                // Harvester only ships CDI (DataVolumes) in newer releases; without it there is simply nothing to sync
                log.info("CDI DataVolume API not available on this Harvester cluster - skipping DataVolume sync")
                ret.success = true
            } else {
                log.error("Failed to fetch DataVolumes from Harvester: ${dataVolumesResponse.msg}, errorCode:${dataVolumesResponse.errorCode}")
                ret.success = false
                ret.message = dataVolumesResponse.msg ?: 'Failed to fetch DataVolumes from Harvester'
            }
        } catch (Exception e) {
            log.error("Error fetching DataVolumes from Harvester", e)
            ret.success = false
            ret.message = "Error fetching DataVolumes: ${e.message}"
        }
        return ret
    }

    static boolean isCdiNotInstalled(ServiceResponse response) {
        String code = response?.errorCode?.toString()
        return code == '404' || response?.msg?.toString()?.toLowerCase()?.contains('404')
    }
}
